_mark compare__mark--no" aria-hidden="true"></span>{% if props.excluded_label is not empty %}<span class="compare__sr">{{ props.excluded_label }}</span>{% endif %}{% endif %}</td>{% endfor %}</tr>{% endfor %}</tbody>{% if has_links %}<tfoot><tr><td class="compare__corner"></td>{% for plan in props.plans %}<td class="compare__cell compare__cell--action{% if plan.highlighted %} compare__cell--highlighted{% endif %}">{% if plan.link and plan.link_label is not empty %}<a class="compare__link{% if plan.highlighted %} compare__link--highlighted{% endif %}" href="{{ plan.link }}">{{ plan.link_label }}</a>{% endif %}</td>{% endfor %}</tr></tfoot>{% endif %}</table></div></section>","css":".compare__title { margin: 0 0 0.75rem; }
.compare__intro { margin: 0 0 1.5rem; color: var(--cms-color-text-muted); max-width: 48rem; }
.compare__scroll { overflow-x: auto; border: 1px solid var(--cms-color-border); border-radius: 0.5rem; }
.compare__scroll:focus-visible { outline: 2px solid var(--cms-color-accent); outline-offset: 2px; }
.compare__table { width: 100%; min-width: 36rem; border-collapse: collapse; background: var(--cms-color-surface); color: var(--cms-color-text); }
.compare__table th, .compare__table td { padding: 0.75rem 1rem; border-bottom: 1px solid var(--cms-color-border); vertical-align: middle; }
.compare__table tbody tr:last-child th, .compare__table tbody tr:last-child td { border-bottom: 0; }
.compare__corner { text-align: left; font-weight: 600; color: var(--cms-color-text-muted); }
.compare__plan { text-align: center; vertical-align: bottom; }
.compare__tag { display: inline-block; margin-bottom: 0.35rem; padding: 0.15rem 0.6rem; border-radius: 999px; background: var(--cms-color-accent); color: var(--cms-color-on-accent); font-size: 0.75rem; font-weight: 600; }
.compare__name { display: block; font-size: 1.125rem; font-weight: 700; }
.compare__plan--highlighted, .compare__cell--highlighted { background: var(--cms-color-accent-surface); }
.compare__plan--highlighted { border-top: 3px solid var(--cms-color-accent); }
.compare__feature { text-align: left; font-weight: 600; }
.compare__cell { text-align: center; }
.compare__value { display: inline-block; }
.compare__mark { display: inline-block; font-weight: 700; line-height: 1; }
.compare__mark--yes::before { content: "✓"; color: var(--cms-color-accent-strong); font-size: 1.25rem; }
.compare__mark--yes + .compare__sr + .compare__value { display: block; margin-top: 0.25rem; font-size: 0.875rem; color: var(--cms-color-text-muted); }
.compare__mark--no::before { content: "–"; color: var(--cms-color-text-faint); }
.compare__sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.compare__cell--action { padding-top: 1rem; padding-bottom: 1rem; }
.compare__link { display: inline-block; padding: 0.6rem 1rem; border: 2px solid var(--cms-color-accent); border-radius: 0.375rem; color: var(--cms-color-accent-strong); font-weight: 600; text-decoration: none; transition: background-color 0.2s, color 0.2s; }
.compare__link--highlighted { background: var(--cms-color-accent); color: var(--cms-color-on-accent); }
.compare__link:hover, .compare__link:focus-visible { background: var(--cms-color-accent-strong); border-color: var(--cms-color-accent-strong); color: var(--cms-color-on-accent); }
@media (min-width: 48rem) { .compare__table th, .compare__table td { padding: 1rem 1.25rem; } .compare__feature, .compare__corner { width: 30%; } }"}
